CreditValueByMonth = {
	data: [],
	init: async function (app, container) {
		var defaultCurrency = app.Config.B2B.DefaultCurrency
			? app.Config.B2B.DefaultCurrency
			: "EUR";

        $("[name=currencyDropdown]", container).kendoDropDownList({
            dataSource: app.Config.B2B.Currencies ? app.Config.B2B.Currencies : ["USD", "EUR", "GBP"],
            change: async function (e) {
                var value = this.value();
				var data = await CreditValueByMonth.getData(app, value);
                CreditValueByMonth.initCreditValueChart(container, data, value);
            }
        }).data("kendoDropDownList");

		var data = await this.getData(app, defaultCurrency);
		this.initCreditValueChart(container, data, defaultCurrency);

        $("[name=currencyDropdown]", container).data("kendoDropDownList").value(defaultCurrency);
	},

	getData: async function(app, currency) {
		if(this.data.length > 0)
			return this.data.filter(d => d.Currency == currency).slice(0, 12);

		var query = "B2B/Credit/StatsByCalendarMonth(SystemId='" + app.Config.B2B.TransactionSource + "')";
		var data = (await api.get(query)).value;

		data = data.sort(function(a,b) {
			return new Date(b.CalendarMonth + "-01") - new Date(a.CalendarMonth + "-01");
		});

		data = data.map(d => {
			d.CalendarMonth = new Date(d.CalendarMonth).toISOString().substring(0, 7);
			return d;
		});

		this.data = data.reverse();

		return data.filter(d => d.Currency == currency).slice(0, 12);
	},

	initCreditValueChart: function(container, data, currency) {
		var categories = [... new Set(data.map(i => new Date(i.CalendarMonth)))].map(c => c.toISOString().substring(0, 7));

		var args = {
			showLegend: true,
			series: [
				{
					name: "[resource_displayname[GrossValue]] (" + currency + ")", 
					data: categories.map(c => data.filter(d => d.CalendarMonth == c).flat().map(d => d.Sum))
				}
			],
			categories: categories,
			max: data.map(i =>  Math.round(Math.abs(i.Sum))).sort(function(a,b){return b - a})[0] + 5,
			type: "column"
		};

		return new Chart($("[name=chart]", container), args).init();
	}
};
